WITH combined_sales AS (SELECT ss.ss_item_sk AS item_sk, ss.ss_quantity AS qty, ss.ss_net_profit AS profit, CASE WHEN hd.hd_buy_potential = 'HIGH' THEN 1 ELSE 0 END AS high_buy_pot_flag, td.t_hour AS sale_hour FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN time_dim td ON ss.ss_sold_time_sk = td.t_time_sk UNION ALL SELECT ws.ws_item_sk AS item_sk, ws.ws_quantity AS qty, ws.ws_net_profit AS profit, CASE WHEN hd.hd_buy_potential = 'HIGH' THEN 1 ELSE 0 END AS high_buy_pot_flag, td.t_hour AS sale_hour FROM web_sales ws JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk) SELECT cs.item_sk, SUM(cs.qty) AS total_quantity, SUM(cs.profit) AS total_profit, SUM(cs.high_buy_pot_flag) AS high_buy_pot_sales, MAX(cs.sale_hour) AS latest_sale_hour, DENSE_RANK() OVER (ORDER BY SUM(cs.qty) DESC) AS quantity_rank, CASE WHEN SUM(cs.profit) > 0 THEN SUM(cs.profit) * 1.1 ELSE SUM(cs.profit) * 0.9 END AS adjusted_profit FROM combined_sales cs GROUP BY cs.item_sk HAVING SUM(cs.qty) > 0 ORDER BY quantity_rank LIMIT 10
